using Marten;
using Wolverine.Http;

namespace Allocation.Views;

/// <summary>
/// What the Pool Desk screen reads. A GT asserts THROUGH THIS, not against the document store, because
/// that covers the projection AND the query surface — which is what a caller actually gets.
/// </summary>
public static class PoolAvailabilityEndpoint
{
    public const string Route = "/pools/{poolId}/availability";

    /// <summary>
    /// 404 rather than an empty row for a pool nobody opened. The row's absence is also what "the daemon
    /// has not caught up" looks like, and the two are genuinely indistinguishable from here — which is the
    /// honest cost of this view being Async and is why nothing decides anything from it.
    /// </summary>
    [WolverineGet(Route)]
    public static async Task<IResult> Get(Guid poolId, IQuerySession session, CancellationToken cancellation)
    {
        var row = await session.LoadAsync<PoolAvailability>(poolId, cancellation);
        return row is null ? Results.NotFound() : Results.Ok(row);
    }
}
